//! A byte-faithful reimplementation of the C++ `url_parser::URL` class.
//!
//! Components are held as raw bytes rather than `String`s so that any argument
//! the shell hands over survives untouched: the parser never inspects anything
//! but ASCII delimiters, and never re-encodes or percent-decodes.

mod parser;
mod port;
mod serialize;

pub use port::NO_PORT;

/// The raw components produced by the splitting pass.
pub(crate) struct Parts {
    pub scheme: Vec<u8>,
    pub userinfo: Vec<u8>,
    pub host: Vec<u8>,
    pub port: i32,
    pub path: Vec<u8>,
    pub query: Vec<u8>,
    pub fragment: Vec<u8>,
}

/// A parsed URL, mirroring `url_parser::URL`.
pub struct Url {
    parts: Parts,
    authority: Vec<u8>,
    serialized: Vec<u8>,
}

impl Url {
    /// Parses `input`, mirroring the `URL(const std::string&)` constructor.
    pub fn new(input: &[u8]) -> Self {
        let parts = parser::parse(input);
        let authority = serialize::authority(&parts);
        let serialized = serialize::to_string(&parts);
        Url {
            parts,
            authority,
            serialized,
        }
    }

    pub fn scheme(&self) -> &[u8] {
        &self.parts.scheme
    }

    /// The authority rebuilt from userinfo, host and port — not the original
    /// substring.
    pub fn authority(&self) -> &[u8] {
        &self.authority
    }

    pub fn userinfo(&self) -> &[u8] {
        &self.parts.userinfo
    }

    pub fn host(&self) -> &[u8] {
        &self.parts.host
    }

    /// The port, or [`NO_PORT`] (`-1`) when absent or unusable.
    pub fn port(&self) -> i32 {
        self.parts.port
    }

    pub fn path(&self) -> &[u8] {
        &self.parts.path
    }

    pub fn query(&self) -> &[u8] {
        &self.parts.query
    }

    pub fn fragment(&self) -> &[u8] {
        &self.parts.fragment
    }

    pub fn has_scheme(&self) -> bool {
        !self.parts.scheme.is_empty()
    }

    /// True exactly when there is a host: a userinfo or port on its own does
    /// not count, so `"http://:8080"` has no authority even though
    /// [`Url::authority`] renders as `":8080"`.
    pub fn has_authority(&self) -> bool {
        self.has_host()
    }

    pub fn has_userinfo(&self) -> bool {
        !self.parts.userinfo.is_empty()
    }

    pub fn has_host(&self) -> bool {
        !self.parts.host.is_empty()
    }

    pub fn has_port(&self) -> bool {
        self.parts.port != NO_PORT
    }

    pub fn has_path(&self) -> bool {
        !self.parts.path.is_empty()
    }

    pub fn has_query(&self) -> bool {
        !self.parts.query.is_empty()
    }

    pub fn has_fragment(&self) -> bool {
        !self.parts.fragment.is_empty()
    }

    /// The URL rebuilt from its components; lossy where the input carried
    /// something unrepresentable, such as an unusable port or an empty query.
    pub fn to_string(&self) -> &[u8] {
        &self.serialized
    }

    /// True when either a host or a path was found. A query or fragment alone
    /// is not enough, so `"?q=1"` is invalid while `" "` is valid.
    pub fn is_valid(&self) -> bool {
        self.has_host() || self.has_path()
    }
}

